alter table public.invoice_items add column if not exists company_id uuid;
update public.invoice_items ii set company_id=i.company_id from public.invoices i where i.id=ii.invoice_id and ii.company_id is null;
alter table public.invoice_items alter column company_id set not null;
alter table public.invoice_items add constraint invoice_items_company_fk foreign key(company_id) references public.companies(id) on delete cascade;
create index if not exists idx_invoice_items_company on public.invoice_items(company_id);
alter table public.invoices enable row level security; alter table public.invoice_items enable row level security;
drop policy if exists invoices_company_select on public.invoices; create policy invoices_company_select on public.invoices for select to authenticated using(company_id=public.get_my_company_id());
drop policy if exists invoices_company_write on public.invoices; create policy invoices_company_write on public.invoices for insert to authenticated with check(company_id=public.get_my_company_id() and public.has_permission('payments.manage'));
drop policy if exists invoices_company_update on public.invoices; create policy invoices_company_update on public.invoices for update to authenticated using(company_id=public.get_my_company_id() and public.has_permission('payments.manage')) with check(company_id=public.get_my_company_id() and public.has_permission('payments.manage'));
drop policy if exists invoice_items_company_select on public.invoice_items; create policy invoice_items_company_select on public.invoice_items for select to authenticated using(company_id=public.get_my_company_id());
drop policy if exists invoice_items_company_write on public.invoice_items; create policy invoice_items_company_write on public.invoice_items for insert to authenticated with check(company_id=public.get_my_company_id() and public.has_permission('payments.manage') and exists(select 1 from invoices i where i.id=invoice_id and i.company_id=public.get_my_company_id()));
create or replace function public.create_invoice(p_invoice_number text,p_customer_id uuid default null,p_repair_id uuid default null,p_sale_id uuid default null,p_subtotal numeric default 0,p_discount numeric default 0,p_total numeric default 0,p_due_at timestamptz default null,p_notes text default null) returns uuid language plpgsql security definer set search_path='public' as $$ declare v_id uuid; v_company uuid; v_branch uuid; begin if auth.uid() is null then raise exception 'Not authenticated'; end if; if not public.has_permission('payments.manage') then raise exception 'Permission denied'; end if; v_company:=public.get_my_company_id(); if v_company is null then raise exception 'Company not found'; end if; if trim(coalesce(p_invoice_number,''))='' then raise exception 'Invoice number is required'; end if; if p_subtotal<0 or p_discount<0 or p_total<0 or p_discount>p_subtotal then raise exception 'Invalid invoice amounts'; end if; if p_customer_id is not null and not exists(select 1 from customers where id=p_customer_id and company_id=v_company) then raise exception 'Customer not found'; end if; if p_repair_id is not null then select branch_id into v_branch from repairs where id=p_repair_id and company_id=v_company; if not found then raise exception 'Repair not found'; end if; elsif p_sale_id is not null then select branch_id into v_branch from sales where id=p_sale_id and company_id=v_company; if not found then raise exception 'Sale not found'; end if; end if; insert into invoices(company_id,branch_id,customer_id,repair_id,sale_id,invoice_number,subtotal,discount,total,due_at,notes,created_by) values(v_company,v_branch,p_customer_id,p_repair_id,p_sale_id,trim(p_invoice_number),p_subtotal,p_discount,p_total,p_due_at,p_notes,auth.uid()) returning id into v_id; return v_id; end; $$;
grant execute on function public.create_invoice(text,uuid,uuid,uuid,numeric,numeric,numeric,timestamptz,text) to authenticated; revoke execute on function public.create_invoice(text,uuid,uuid,uuid,numeric,numeric,numeric,timestamptz,text) from anon;
create or replace function public.add_invoice_item(p_invoice_id uuid,p_description text,p_quantity numeric default 1,p_unit_price numeric default 0) returns uuid language plpgsql security definer set search_path='public' as $$ declare v_company uuid; v_id uuid; begin if auth.uid() is null then raise exception 'Not authenticated'; end if; if not public.has_permission('payments.manage') then raise exception 'Permission denied'; end if; select company_id into v_company from invoices where id=p_invoice_id; if v_company is null or v_company<>public.get_my_company_id() then raise exception 'Invoice not found'; end if; if trim(coalesce(p_description,''))='' or p_quantity<=0 or p_unit_price<0 then raise exception 'Invalid invoice item'; end if; insert into invoice_items(invoice_id,company_id,description,quantity,unit_price) values(p_invoice_id,v_company,trim(p_description),p_quantity,p_unit_price) returning id into v_id; return v_id; end; $$;
grant execute on function public.add_invoice_item(uuid,text,numeric,numeric) to authenticated; revoke execute on function public.add_invoice_item(uuid,text,numeric,numeric) from anon;
